impl std::fmt::Debug for PortalService {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_tuple("PortalService")
            .field(&crate::gir::ObjectType::as_object(self).as_ptr())
            .finish()
    }
}

crate::gir::owned::release!(PortalService, |object| {
    // SAFETY: on frida-core's thread, with an instance of PortalService; the async form
    // with no callback starts the release and frees its own state when done.
    unsafe {
        frida_sys::frida_portal_service_stop(
            object.cast(),
            std::ptr::null_mut(),
            None,
            std::ptr::null_mut(),
        );
    }
});

impl crate::gir::Owned<PortalService> {
    /// Stops the portal, disconnecting everyone and releasing its endpoints.
    ///
    /// Calls `frida_portal_service_stop_sync`.
    ///
    /// # Errors
    ///
    /// - frida-core's error, if the call fails.
    /// - [`ErrorKind::Cancelled`](crate::gir::ErrorKind::Cancelled), if `cancellable` is cancelled.
    ///
    /// Consumes the owner, and returns the error that dropping it would discard. Unlike
    /// dropping it, this waits for the release to finish.
    pub fn stop(
        self,
        cancellable: Option<&crate::gir::Cancellable>,
    ) -> Result<(), crate::gir::Error> {
        self.keep().stop(cancellable)
    }
}
